window.GAOKAO_PAPERS=window.GAOKAO_PAPERS||{};window.GAOKAO_PAPERS["2024-new_gaokao_paper_1"]=[{"id":"2024-new_gaokao_paper_1-q01","paperId":"2024-new_gaokao_paper_1","number":1,"type":"single","score":5,"lessonIds":["1.3"],"difficulty":"基础","hint":"先估出三次根号5在1与2之间，再从B的五个数里挑同时落在A范围内的数。","legacy":false,"legacyReason":"","searchText":"已知集合 A=\\{x\\mid -5<x^3<5\\} ， B=\\{-3,-1,0,2,3\\} ，则 A\\cap B= （ ） \\{-1,0\\} \\{2,3\\} \\{-3,-1,0\\} \\{-1,0,2\\}","questionHtml":"已知集合 <span class=\"gk-math\" data-tex=\"A=\\{x\\mid -5&lt;x^3&lt;5\\}\">A=\\{x\\mid -5&lt;x^3&lt;5\\}</span>，<span class=\"gk-math\" data-tex=\"B=\\{-3,-1,0,2,3\\}\">B=\\{-3,-1,0,2,3\\}</span>，则 <span class=\"gk-math\" data-tex=\"A\\cap B=\">A\\cap B=</span>（ ）","optionsHtml":["<span class=\"gk-math\" data-tex=\"\\{-1,0\\}\">\\{-1,0\\}</span>","<span class=\"gk-math\" data-tex=\"\\{2,3\\}\">\\{2,3\\}</span>","<span class=\"gk-math\" data-tex=\"\\{-3,-1,0\\}\">\\{-3,-1,0\\}</span>","<span class=\"gk-math\" data-tex=\"\\{-1,0,2\\}\">\\{-1,0,2\\}</span>"],"answerHtml":"A","answerKey":"A","solutionHtml":"因为 <span class=\"gk-math\" data-tex=\"1&lt;\\sqrt[3]{5}&lt;2\">1&lt;\\sqrt[3]{5}&lt;2</span>，所以 <div class=\"gk-math display\" data-tex=\"-\\sqrt[3]{5}&lt;-1&lt;0&lt;\\sqrt[3]{5}\">-\\sqrt[3]{5}&lt;-1&lt;0&lt;\\sqrt[3]{5}</div> 而 <span class=\"gk-math\" data-tex=\"-3\">-3</span>，<span class=\"gk-math\" data-tex=\"2\">2</span>，<span class=\"gk-math\" data-tex=\"3\">3</span> 都不在区间 <span class=\"gk-math\" data-tex=\"\\left(-\\sqrt[3]{5},\\sqrt[3]{5}\\right)\">\\left(-\\sqrt[3]{5},\\sqrt[3]{5}\\right)</span> 内，因此 <span class=\"gk-math\" data-tex=\"A\\cap B=\\{-1,0\\}\">A\\cap B=\\{-1,0\\}</span>. 故选 A.","sourceNote":"","specialNote":"","answerAlternatives":[]},{"id":"2024-new_gaokao_paper_1-q02","paperId":"2024-new_gaokao_paper_1","number":2,"type":"single","score":5,"lessonIds":["7.2"],"difficulty":"基础","hint":"先把等式两边乘以z−1，把所有含z的项移到一边，再用i²=−1化简。","legacy":false,"legacyReason":"","searchText":"若 \\dfrac{z}{z-1}=1+\\i ，则 z= （ ） -1-\\i -1+\\i 1-\\i 1+\\i","questionHtml":"若 <span class=\"gk-math\" data-tex=\"\\dfrac{z}{z-1}=1+\\i\">\\dfrac{z}{z-1}=1+\\i</span>，则 <span class=\"gk-math\" data-tex=\"z=\">z=</span>（ ）","optionsHtml":["<span class=\"gk-math\" data-tex=\"-1-\\i\">-1-\\i</span>","<span class=\"gk-math\" data-tex=\"-1+\\i\">-1+\\i</span>","<span class=\"gk-math\" data-tex=\"1-\\i\">1-\\i</span>","<span class=\"gk-math\" data-tex=\"1+\\i\">1+\\i</span>"],"answerHtml":"C","answerKey":"C","solutionHtml":"由 <span class=\"gk-math\" data-tex=\"\\frac{z}{z-1}=1+\\i\">\\frac{z}{z-1}=1+\\i</span> 得 <span class=\"gk-math\" data-tex=\"z=(1+\\i)(z-1)\">z=(1+\\i)(z-1)</span>. 所以 <span class=\"gk-math\" data-tex=\"\\i z=-(1+\\i)\">\\i z=-(1+\\i)</span>， 从而 <span class=\"gk-math\" data-tex=\"z=\\frac{-(1+\\i)}{\\i}=1-\\i\">z=\\frac{-(1+\\i)}{\\i}=1-\\i</span>. 故选 C.","sourceNote":"","specialNote":"","answerAlternatives":[]},{"id":"2024-new_gaokao_paper_1-q03","paperId":"2024-new_gaokao_paper_1","number":3,"type":"single","score":5,"lessonIds":["6.3"],"difficulty":"基础","hint":"先算b−4a=(2,x−4)，两个向量垂直，就让对应坐标乘积的和等于0。","legacy":false,"legacyReason":"","searchText":"已知向量 \\bs a=(0,1) ， \\bs b=(2,x) ，若 \\bs b\\perp (\\bs b-4\\bs a) ，则 x= （ ） -2 -1 1 2","questionHtml":"已知向量 <span class=\"gk-math\" data-tex=\"\\bs a=(0,1)\">\\bs a=(0,1)</span>，<span class=\"gk-math\" data-tex=\"\\bs b=(2,x)\">\\bs b=(2,x)</span>，若 <span class=\"gk-math\" data-tex=\"\\bs b\\perp (\\bs b-4\\bs a)\">\\bs b\\perp (\\bs b-4\\bs a)</span>，则 <span class=\"gk-math\" data-tex=\"x=\">x=</span>（ ）","optionsHtml":["<span class=\"gk-math\" data-tex=\"-2\">-2</span>","<span class=\"gk-math\" data-tex=\"-1\">-1</span>","<span class=\"gk-math\" data-tex=\"1\">1</span>","<span class=\"gk-math\" data-tex=\"2\">2</span>"],"answerHtml":"D","answerKey":"D","solutionHtml":"由 <span class=\"gk-math\" data-tex=\"\\bs b\\perp (\\bs b-4\\bs a)\">\\bs b\\perp (\\bs b-4\\bs a)</span>，得 <span class=\"gk-math\" data-tex=\"\\bs b\\cdot (\\bs b-4\\bs a)=0\">\\bs b\\cdot (\\bs b-4\\bs a)=0</span>. 即 <span class=\"gk-math\" data-tex=\"(2,x)\\cdot\\left(2,x-4\\right)=4+x(x-4)=0\">(2,x)\\cdot\\left(2,x-4\\right)=4+x(x-4)=0</span>. 故 <span class=\"gk-math\" data-tex=\"x^2-4x+4=0\">x^2-4x+4=0</span>，所以 <span class=\"gk-math\" data-tex=\"x=2\">x=2</span>（题中仅有一个取值）. 故选 D.","sourceNote":"","specialNote":"","answerAlternatives":[]},{"id":"2024-new_gaokao_paper_1-q04","paperId":"2024-new_gaokao_paper_1","number":4,"type":"single","score":5,"lessonIds":["5.5"],"difficulty":"进阶","hint":"先展开cos(α+β)，再把tanαtanβ=2改写成sinαsinβ=2cosαcosβ。","legacy":false,"legacyReason":"","searchText":"已知 \\cos(\\alpha+\\beta)=m ， \\tan\\alpha\\tan\\beta=2 ，则 \\cos(\\alpha-\\beta)= （ ） -3m -\\frac{m}{3} \\frac{m}{3} 3m","questionHtml":"已知 <span class=\"gk-math\" data-tex=\"\\cos(\\alpha+\\beta)=m\">\\cos(\\alpha+\\beta)=m</span>，<span class=\"gk-math\" data-tex=\"\\tan\\alpha\\tan\\beta=2\">\\tan\\alpha\\tan\\beta=2</span>，则 <span class=\"gk-math\" data-tex=\"\\cos(\\alpha-\\beta)=\">\\cos(\\alpha-\\beta)=</span>（ ）","optionsHtml":["<span class=\"gk-math\" data-tex=\"-3m\">-3m</span>","<span class=\"gk-math\" data-tex=\"-\\frac{m}{3}\">-\\frac{m}{3}</span>","<span class=\"gk-math\" data-tex=\"\\frac{m}{3}\">\\frac{m}{3}</span>","<span class=\"gk-math\" data-tex=\"3m\">3m</span>"],"answerHtml":"A","answerKey":"A","solutionHtml":"由 <span class=\"gk-math\" data-tex=\"\\cos(\\alpha+\\beta)=m\">\\cos(\\alpha+\\beta)=m</span> 得 <span class=\"gk-math\" data-tex=\"\\cos\\alpha\\cos\\beta-\\sin\\alpha\\sin\\beta=m\">\\cos\\alpha\\cos\\beta-\\sin\\alpha\\sin\\beta=m</span>. 又 <span class=\"gk-math\" data-tex=\"\\tan\\alpha\\tan\\beta=2\">\\tan\\alpha\\tan\\beta=2</span>，故 <span class=\"gk-math\" data-tex=\"\\sin\\alpha\\sin\\beta=2\\cos\\alpha\\cos\\beta\">\\sin\\alpha\\sin\\beta=2\\cos\\alpha\\cos\\beta</span>. 于是 <span class=\"gk-math\" data-tex=\"\\cos\\alpha\\cos\\beta-2\\cos\\alpha\\cos\\beta=m\">\\cos\\alpha\\cos\\beta-2\\cos\\alpha\\cos\\beta=m</span> 即 <span class=\"gk-math\" data-tex=\"\\cos\\alpha\\cos\\beta=-m\">\\cos\\alpha\\cos\\beta=-m</span>. 从而 <div class=\"gk-math display\" data-tex=\"\\cos(\\alpha-\\beta)=\\cos\\alpha\\cos\\beta+\\sin\\alpha\\sin\\beta=(-m)+2(-m)=-3m\">\\cos(\\alpha-\\beta)=\\cos\\alpha\\cos\\beta+\\sin\\alpha\\sin\\beta=(-m)+2(-m)=-3m</div> 故选 A.","sourceNote":"","specialNote":"","answerAlternatives":[]},{"id":"2024-new_gaokao_paper_1-q05","paperId":"2024-new_gaokao_paper_1","number":5,"type":"single","score":5,"lessonIds":["8.3"],"difficulty":"基础","hint":"把共同半径设为r，先用侧面积相等求圆锥母线，再用母线、高、半径组成的直角三角形求r。","legacy":false,"legacyReason":"","searchText":"已知圆柱和圆锥的底面半径相等，侧面积相等，且它们的高均为 \\sqrt3 ，则圆锥的体积为（ ） 2\\sqrt3\\pi 3\\sqrt3\\pi 6\\sqrt3\\pi 9\\sqrt3\\pi","questionHtml":"已知圆柱和圆锥的底面半径相等，侧面积相等，且它们的高均为 <span class=\"gk-math\" data-tex=\"\\sqrt3\">\\sqrt3</span>，则圆锥的体积为（ ）","optionsHtml":["<span class=\"gk-math\" data-tex=\"2\\sqrt3\\pi\">2\\sqrt3\\pi</span>","<span class=\"gk-math\" data-tex=\"3\\sqrt3\\pi\">3\\sqrt3\\pi</span>","<span class=\"gk-math\" data-tex=\"6\\sqrt3\\pi\">6\\sqrt3\\pi</span>","<span class=\"gk-math\" data-tex=\"9\\sqrt3\\pi\">9\\sqrt3\\pi</span>"],"answerHtml":"B","answerKey":"B","solutionHtml":"设圆柱和圆锥的底面半径都为 <span class=\"gk-math\" data-tex=\"r\">r</span>. 圆锥的母线长为 <span class=\"gk-math\" data-tex=\"l=\\sqrt{r^2+(\\sqrt3)^2}=\\sqrt{r^2+3}\">l=\\sqrt{r^2+(\\sqrt3)^2}=\\sqrt{r^2+3}</span>. 侧面积相等给出 <span class=\"gk-math\" data-tex=\"2\\pi r\\cdot \\sqrt3=\\pi rl\">2\\pi r\\cdot \\sqrt3=\\pi rl</span> 即 <span class=\"gk-math\" data-tex=\"\\sqrt{r^2+3}=2\\sqrt3\">\\sqrt{r^2+3}=2\\sqrt3</span>， 故 <span class=\"gk-math\" data-tex=\"r^2=9\">r^2=9</span>. 所以 <span class=\"gk-math\" data-tex=\"r=3\">r=3</span>. 圆锥体积 <div class=\"gk-math display\" data-tex=\"V=\\frac13\\pi r^2\\cdot \\sqrt3=\\frac13\\pi\\cdot 9\\cdot \\sqrt3=3\\sqrt3\\pi\">V=\\frac13\\pi r^2\\cdot \\sqrt3=\\frac13\\pi\\cdot 9\\cdot \\sqrt3=3\\sqrt3\\pi</div> 故选 B.","sourceNote":"","specialNote":"","answerAlternatives":[]},{"id":"2024-new_gaokao_paper_1-q06","paperId":"2024-new_gaokao_paper_1","number":6,"type":"single","score":5,"lessonIds":["3.2","2.3"],"difficulty":"进阶","hint":"分开检查x<0和x≥0两段是否递增，还要比较左段靠近0的值与f(0)，不能只看每一段。","legacy":false,"legacyReason":"","searchText":"已知函数 f(x)=-x^2-2ax-a （ x<0 ）， f(x)=\\e^x+\\ln(x+1) （ x\\ge 0 ） 在 \\R 上单调递增，则 a 取值范围为（ ） (-\\infty,0] [-1,0] [-1,1] [0,+\\infty)","questionHtml":"已知函数 <span class=\"gk-math\" data-tex=\"f(x)=-x^2-2ax-a\">f(x)=-x^2-2ax-a</span>（<span class=\"gk-math\" data-tex=\"x&lt;0\">x&lt;0</span>），<span class=\"gk-math\" data-tex=\"f(x)=\\e^x+\\ln(x+1)\">f(x)=\\e^x+\\ln(x+1)</span>（<span class=\"gk-math\" data-tex=\"x\\ge 0\">x\\ge 0</span>） 在 <span class=\"gk-math\" data-tex=\"\\R\">\\R</span> 上单调递增，则 <span class=\"gk-math\" data-tex=\"a\">a</span> 取值范围为（ ）","optionsHtml":["<span class=\"gk-math\" data-tex=\"(-\\infty,0]\">(-\\infty,0]</span>","<span class=\"gk-math\" data-tex=\"[-1,0]\">[-1,0]</span>","<span class=\"gk-math\" data-tex=\"[-1,1]\">[-1,1]</span>","<span class=\"gk-math\" data-tex=\"[0,+\\infty)\">[0,+\\infty)</span>"],"answerHtml":"B","answerKey":"B","solutionHtml":"当 <span class=\"gk-math\" data-tex=\"x\\ge 0\">x\\ge 0</span> 时， <span class=\"gk-math\" data-tex=\"f(x)=\\e^x+\\ln(x+1)\">f(x)=\\e^x+\\ln(x+1)</span>， 故 <span class=\"gk-math\" data-tex=\"f&#x27;(x)=\\e^x+\\frac1{x+1}&gt;0\">f&#x27;(x)=\\e^x+\\frac1{x+1}&gt;0</span>， 于是右侧部分严格递增.<br><br>对 <span class=\"gk-math\" data-tex=\"x&lt;0\">x&lt;0</span>，有 <span class=\"gk-math\" data-tex=\"f&#x27;(x)=-2x-2a\">f&#x27;(x)=-2x-2a</span>. 要使该部分单调递增需 <span class=\"gk-math\" data-tex=\"f&#x27;(x)\\ge 0\">f&#x27;(x)\\ge 0</span>，即 <span class=\"gk-math\" data-tex=\"-2x-2a\\ge 0\">-2x-2a\\ge 0</span>，对 <span class=\"gk-math\" data-tex=\"x&lt;0\">x&lt;0</span> 最严格在 <span class=\"gk-math\" data-tex=\"x\\to0^-\">x\\to0^-</span> 时取到，故 <span class=\"gk-math\" data-tex=\"-2a\\ge 0\">-2a\\ge 0</span>，即 <span class=\"gk-math\" data-tex=\"a\\le0\">a\\le0</span>.<br><br>此外，单调性要求左侧极限不超过右侧端点值，即 <div class=\"gk-math display\" data-tex=\"\\lim\\limits_{x\\to0^-}f(x)=-a\\le f(0)=\\e^0+\\ln1=1\">\\lim\\limits_{x\\to0^-}f(x)=-a\\le f(0)=\\e^0+\\ln1=1</div> 故 <span class=\"gk-math\" data-tex=\"-a\\le1\">-a\\le1</span>，即 <span class=\"gk-math\" data-tex=\"a\\ge-1\">a\\ge-1</span>. 故 <span class=\"gk-math\" data-tex=\"a\\in[-1,0]\">a\\in[-1,0]</span>.","sourceNote":"","specialNote":"","answerAlternatives":[]},{"id":"2024-new_gaokao_paper_1-q07","paperId":"2024-new_gaokao_paper_1","number":7,"type":"single","score":5,"lessonIds":["5.6","5.4"],"difficulty":"挑战","hint":"先在同一坐标系画出两个正弦波，标出第二条曲线的零点与峰谷，再逐段数交点。","legacy":false,"legacyReason":"","searchText":"当 x\\in[0,2\\pi] 时，曲线 y=\\sin x 与 y=2\\sin\\!\\left(3x-\\frac{\\pi}{6}\\right) 的交点个数为（ ） 3 4 6 8","questionHtml":"当 <span class=\"gk-math\" data-tex=\"x\\in[0,2\\pi]\">x\\in[0,2\\pi]</span> 时，曲线 <span class=\"gk-math\" data-tex=\"y=\\sin x\">y=\\sin x</span> 与 <span class=\"gk-math\" data-tex=\"y=2\\sin\\!\\left(3x-\\frac{\\pi}{6}\\right)\">y=2\\sin\\!\\left(3x-\\frac{\\pi}{6}\\right)</span> 的交点个数为（ ）","optionsHtml":["3","4","6","8"],"answerHtml":"C","answerKey":"C","solutionHtml":"设 <span class=\"gk-math\" data-tex=\"h(x)=\\sin x-2\\sin\\left(3x-\\frac{\\pi}{6}\\right)\">h(x)=\\sin x-2\\sin\\left(3x-\\frac{\\pi}{6}\\right)</span>. 题目所求即为方程 <span class=\"gk-math\" data-tex=\"h(x)=0\">h(x)=0</span> 在 <span class=\"gk-math\" data-tex=\"[0,2\\pi]\">[0,2\\pi]</span> 上解的个数.<br><br>因为 <span class=\"gk-math\" data-tex=\"h(x+\\pi)=\\sin(x+\\pi)-2\\sin\\left(3x+\\frac{17\\pi}{6}\\right)=-h(x)\">h(x+\\pi)=\\sin(x+\\pi)-2\\sin\\left(3x+\\frac{17\\pi}{6}\\right)=-h(x)</span>， 所以 <span class=\"gk-math\" data-tex=\"h(x)=0\">h(x)=0</span> 的解关于平移 <span class=\"gk-math\" data-tex=\"\\pi\">\\pi</span> 成对出现，只需考察区间 <span class=\"gk-math\" data-tex=\"[0,\\pi]\">[0,\\pi]</span>.<br><br>当 <span class=\"gk-math\" data-tex=\"x\\in\\left[\\frac{\\pi}{6},\\frac{\\pi}{3}\\right]\">x\\in\\left[\\frac{\\pi}{6},\\frac{\\pi}{3}\\right]</span> 时，<span class=\"gk-math\" data-tex=\"\\sin x\\le \\frac{\\sqrt3}{2}\">\\sin x\\le \\frac{\\sqrt3}{2}</span>，且 <span class=\"gk-math\" data-tex=\"3x-\\frac{\\pi}{6}\\in\\left[\\frac{\\pi}{3},\\frac{5\\pi}{6}\\right]\">3x-\\frac{\\pi}{6}\\in\\left[\\frac{\\pi}{3},\\frac{5\\pi}{6}\\right]</span>，从而 <span class=\"gk-math\" data-tex=\"\\sin\\left(3x-\\frac{\\pi}{6}\\right)\\ge \\frac12\">\\sin\\left(3x-\\frac{\\pi}{6}\\right)\\ge \\frac12</span>. 于是 <span class=\"gk-math\" data-tex=\"h(x)\\le \\frac{\\sqrt3}{2}-1&lt;0\">h(x)\\le \\frac{\\sqrt3}{2}-1&lt;0</span>. 当 <span class=\"gk-math\" data-tex=\"x\\in\\left[\\frac{\\pi}{2},\\frac{2\\pi}{3}\\right]\">x\\in\\left[\\frac{\\pi}{2},\\frac{2\\pi}{3}\\right]</span> 时，<span class=\"gk-math\" data-tex=\"\\sin x\\ge \\frac{\\sqrt3}{2}\">\\sin x\\ge \\frac{\\sqrt3}{2}</span>，且 <span class=\"gk-math\" data-tex=\"3x-\\frac{\\pi}{6}\\in\\left[\\frac{4\\pi}{3},\\frac{11\\pi}{6}\\right]\">3x-\\frac{\\pi}{6}\\in\\left[\\frac{4\\pi}{3},\\frac{11\\pi}{6}\\right]</span>，从而 <span class=\"gk-math\" data-tex=\"\\sin\\left(3x-\\frac{\\pi}{6}\\right)\\le -\\frac12\">\\sin\\left(3x-\\frac{\\pi}{6}\\right)\\le -\\frac12</span>. 于是 <span class=\"gk-math\" data-tex=\"h(x)\\ge \\frac{\\sqrt3}{2}+1&gt;0\">h(x)\\ge \\frac{\\sqrt3}{2}+1&gt;0</span>. 当 <span class=\"gk-math\" data-tex=\"x\\in\\left[\\frac{5\\pi}{6},\\pi\\right]\">x\\in\\left[\\frac{5\\pi}{6},\\pi\\right]</span> 时，<span class=\"gk-math\" data-tex=\"\\sin x\\le \\frac12\">\\sin x\\le \\frac12</span>，且 <span class=\"gk-math\" data-tex=\"3x-\\frac{\\pi}{6}\\in\\left[\\frac{7\\pi}{3},\\frac{17\\pi}{6}\\right]\">3x-\\frac{\\pi}{6}\\in\\left[\\frac{7\\pi}{3},\\frac{17\\pi}{6}\\right]</span>，其正弦值不小于 <span class=\"gk-math\" data-tex=\"\\frac12\">\\frac12</span>，于是 <span class=\"gk-math\" data-tex=\"h(x)\\le \\frac12-1&lt;0\">h(x)\\le \\frac12-1&lt;0</span>.<br><br><figure class=\"gk-figure\"><button class=\"gk-zoom\" style=\"width:min(100%,497px)\" data-action=\"zoom-image\" data-label=\"高考题图\" data-src=\"./assets/gaokao/figures/2024/new_gaokao_paper_1/q7_fig1.webp\" aria-label=\"放大高考题图\"><img src=\"./assets/gaokao/figures/2024/new_gaokao_paper_1/q7_fig1.webp\" alt=\"高考题图，点击可放大\" width=\"481\" height=\"330\" style=\"aspect-ratio:481/330;width:100%\" loading=\"lazy\"></button></figure><br><br>再看三个剩余区间： <span class=\"gk-math\" data-tex=\"h(0)=1&gt;0\">h(0)=1&gt;0</span>，<span class=\"gk-math\" data-tex=\"h\\left(\\frac{\\pi}{6}\\right)=\\frac12-\\sqrt3&lt;0\">h\\left(\\frac{\\pi}{6}\\right)=\\frac12-\\sqrt3&lt;0</span>， <span class=\"gk-math\" data-tex=\"h\\left(\\frac{\\pi}{3}\\right)=\\frac{\\sqrt3}{2}-1&lt;0\">h\\left(\\frac{\\pi}{3}\\right)=\\frac{\\sqrt3}{2}-1&lt;0</span>，<span class=\"gk-math\" data-tex=\"h\\left(\\frac{\\pi}{2}\\right)=1+\\sqrt3&gt;0\">h\\left(\\frac{\\pi}{2}\\right)=1+\\sqrt3&gt;0</span>， <span class=\"gk-math\" data-tex=\"h\\left(\\frac{2\\pi}{3}\\right)=1+\\frac{\\sqrt3}{2}&gt;0\">h\\left(\\frac{2\\pi}{3}\\right)=1+\\frac{\\sqrt3}{2}&gt;0</span>，<span class=\"gk-math\" data-tex=\"h\\left(\\frac{5\\pi}{6}\\right)=\\frac12-\\sqrt3&lt;0\">h\\left(\\frac{5\\pi}{6}\\right)=\\frac12-\\sqrt3&lt;0</span>. 在三个剩余区间中，<span class=\"gk-math\" data-tex=\"h\">h</span> 的导数依次严格为负、正、负：第一段和第三段的 <span class=\"gk-math\" data-tex=\"\\cos(3x-\\pi/6)\\ge1/2\">\\cos(3x-\\pi/6)\\ge1/2</span>，所以 <span class=\"gk-math\" data-tex=\"h\\prime(x)=\\cos x-6\\cos(3x-\\pi/6)&lt;0\">h\\prime(x)=\\cos x-6\\cos(3x-\\pi/6)&lt;0</span>；中间一段的 <span class=\"gk-math\" data-tex=\"\\cos(3x-\\pi/6)\\le-1/2\">\\cos(3x-\\pi/6)\\le-1/2</span>，所以 <span class=\"gk-math\" data-tex=\"h\\prime(x)&gt;0\">h\\prime(x)&gt;0</span>。因此每段至多一个零点。由介值定理，方程 <span class=\"gk-math\" data-tex=\"h(x)=0\">h(x)=0</span> 在 <span class=\"gk-math\" data-tex=\"\\left(0,\\frac{\\pi}{6}\\right)\">\\left(0,\\frac{\\pi}{6}\\right)</span>，<span class=\"gk-math\" data-tex=\"\\left(\\frac{\\pi}{3},\\frac{\\pi}{2}\\right)\">\\left(\\frac{\\pi}{3},\\frac{\\pi}{2}\\right)</span>，<span class=\"gk-math\" data-tex=\"\\left(\\frac{2\\pi}{3},\\frac{5\\pi}{6}\\right)\">\\left(\\frac{2\\pi}{3},\\frac{5\\pi}{6}\\right)</span> 内各有一个解，而在其余部分没有解，所以在 <span class=\"gk-math\" data-tex=\"[0,\\pi]\">[0,\\pi]</span> 上共有 <span class=\"gk-math\" data-tex=\"3\">3</span> 个解.<br><br>再由 <span class=\"gk-math\" data-tex=\"h(x+\\pi)=-h(x)\">h(x+\\pi)=-h(x)</span>，得到 <span class=\"gk-math\" data-tex=\"[\\pi,2\\pi]\">[\\pi,2\\pi]</span> 上对应地也有 <span class=\"gk-math\" data-tex=\"3\">3</span> 个解. 因此两个曲线在 <span class=\"gk-math\" data-tex=\"[0,2\\pi]\">[0,2\\pi]</span> 上共有 <span class=\"gk-math\" data-tex=\"6\">6</span> 个交点. 故选 C.","sourceNote":"","specialNote":"","answerAlternatives":[]},{"id":"2024-new_gaokao_paper_1-q08","paperId":"2024-new_gaokao_paper_1","number":8,"type":"single","score":5,"lessonIds":["e2-4.1","3.1"],"difficulty":"进阶","hint":"先写f(1)=1、f(2)=2，再用给出的不等式依次得到f(3)、f(4)等的下界。","legacy":false,"legacyReason":"","searchText":"已知函数 f(x) 的定义域为 \\R ，且 f(x)>f(x-1)+f(x-2) ， 当 x<3 时 f(x)=x . 则下列结论中一定正确的是（ ） f(10)>100 f(20)>1000 f(10)<1000 f(20)<10000","questionHtml":"已知函数 <span class=\"gk-math\" data-tex=\"f(x)\">f(x)</span> 的定义域为 <span class=\"gk-math\" data-tex=\"\\R\">\\R</span>，且 <span class=\"gk-math\" data-tex=\"f(x)&gt;f(x-1)+f(x-2)\">f(x)&gt;f(x-1)+f(x-2)</span>， 当 <span class=\"gk-math\" data-tex=\"x&lt;3\">x&lt;3</span> 时 <span class=\"gk-math\" data-tex=\"f(x)=x\">f(x)=x</span>. 则下列结论中一定正确的是（ ）","optionsHtml":["<span class=\"gk-math\" data-tex=\"f(10)&gt;100\">f(10)&gt;100</span>","<span class=\"gk-math\" data-tex=\"f(20)&gt;1000\">f(20)&gt;1000</span>","<span class=\"gk-math\" data-tex=\"f(10)&lt;1000\">f(10)&lt;1000</span>","<span class=\"gk-math\" data-tex=\"f(20)&lt;10000\">f(20)&lt;10000</span>"],"answerHtml":"B","answerKey":"B","solutionHtml":"由题设得 <span class=\"gk-math\" data-tex=\"f(1)=1\">f(1)=1</span>，<span class=\"gk-math\" data-tex=\"f(2)=2\">f(2)=2</span>. 由递推式 <span class=\"gk-math\" data-tex=\"f(x)&gt;f(x-1)+f(x-2)\">f(x)&gt;f(x-1)+f(x-2)</span> 可得 <span class=\"gk-math\" data-tex=\"f(3)&gt;3\">f(3)&gt;3</span>，<span class=\"gk-math\" data-tex=\"f(4)&gt;5\">f(4)&gt;5</span>，<span class=\"gk-math\" data-tex=\"f(5)&gt;8\">f(5)&gt;8</span>，<span class=\"gk-math\" data-tex=\"f(6)&gt;13\">f(6)&gt;13</span>，<span class=\"gk-math\" data-tex=\"\\dots\">\\dots</span>，逐项递增且均大于对应斐波那契数，故 <span class=\"gk-math\" data-tex=\"f(10)&gt;89\">f(10)&gt;89</span>，<span class=\"gk-math\" data-tex=\"f(20)&gt;1597&gt;1000\">f(20)&gt;1597&gt;1000</span>. 故 <span class=\"gk-math\" data-tex=\"f(20)&gt;1000\">f(20)&gt;1000</span> 正确，其他不一定. 故选 B.","sourceNote":"","specialNote":"","answerAlternatives":[]},{"id":"2024-new_gaokao_paper_1-q09","paperId":"2024-new_gaokao_paper_1","number":9,"type":"multiple","score":6,"lessonIds":["e3-7.5","9.2"],"difficulty":"进阶","hint":"先由样本方差0.01算标准差0.1，再看2分别位于两个正态分布均值的哪一侧。","legacy":false,"legacyReason":"","searchText":"随着“一带一路”国际合作的深入，某茶叶种植区多措并举推动茶叶出口。为了解推动出口后的亩收入（单位：万元）情况，从该种植区抽取样本，得到推动出口后亩收入的样本均值 \\bar x=2.1 ，样本方差 s^2=0.01 。已知该种植区以往的亩收入 X 服从正态分布 N(1.8,0.1^2) ，假设推动出口后的亩收入 Y 服从正态分布 N(\\bar x,s^2) ，则（ ）（若随机变量 Z 服从正态分布 N(\\mu,\\sigma^2) ，则 P(Z<\\mu+\\sigma)\\approx0.8413 ） P(X>2)>0.2 P(X>2)<0.5 P(Y>2)>0.5 P(Y>2)<0.8","questionHtml":"随着“一带一路”国际合作的深入，某茶叶种植区多措并举推动茶叶出口。为了解推动出口后的亩收入（单位：万元）情况，从该种植区抽取样本，得到推动出口后亩收入的样本均值 <span class=\"gk-math\" data-tex=\"\\bar x=2.1\">\\bar x=2.1</span>，样本方差 <span class=\"gk-math\" data-tex=\"s^2=0.01\">s^2=0.01</span>。已知该种植区以往的亩收入 <span class=\"gk-math\" data-tex=\"X\">X</span> 服从正态分布 <span class=\"gk-math\" data-tex=\"N(1.8,0.1^2)\">N(1.8,0.1^2)</span>，假设推动出口后的亩收入 <span class=\"gk-math\" data-tex=\"Y\">Y</span> 服从正态分布 <span class=\"gk-math\" data-tex=\"N(\\bar x,s^2)\">N(\\bar x,s^2)</span>，则（ ）（若随机变量 <span class=\"gk-math\" data-tex=\"Z\">Z</span> 服从正态分布 <span class=\"gk-math\" data-tex=\"N(\\mu,\\sigma^2)\">N(\\mu,\\sigma^2)</span>，则 <span class=\"gk-math\" data-tex=\"P(Z&lt;\\mu+\\sigma)\\approx0.8413\">P(Z&lt;\\mu+\\sigma)\\approx0.8413</span>）","optionsHtml":["<span class=\"gk-math\" data-tex=\"P(X&gt;2)&gt;0.2\">P(X&gt;2)&gt;0.2</span>","<span class=\"gk-math\" data-tex=\"P(X&gt;2)&lt;0.5\">P(X&gt;2)&lt;0.5</span>","<span class=\"gk-math\" data-tex=\"P(Y&gt;2)&gt;0.5\">P(Y&gt;2)&gt;0.5</span>","<span class=\"gk-math\" data-tex=\"P(Y&gt;2)&lt;0.8\">P(Y&gt;2)&lt;0.8</span>"],"answerHtml":"BC","answerKey":"BC","solutionHtml":"正态分布 <span class=\"gk-math\" data-tex=\"N(\\mu,\\sigma^2)\">N(\\mu,\\sigma^2)</span> 的第二个参数是方差，所以 <span class=\"gk-math\" data-tex=\"X\">X</span> 的均值是 <span class=\"gk-math\" data-tex=\"1.8\">1.8</span>、标准差是 <span class=\"gk-math\" data-tex=\"0.1\">0.1</span>，<span class=\"gk-math\" data-tex=\"Y\">Y</span> 的均值是 <span class=\"gk-math\" data-tex=\"2.1\">2.1</span>、标准差也是 <span class=\"gk-math\" data-tex=\"\\sqrt{0.01}=0.1\">\\sqrt{0.01}=0.1</span>。<br><br><span class=\"gk-math\" data-tex=\"2&gt;1.8+0.1=1.9\">2&gt;1.8+0.1=1.9</span>，所以 <div class=\"gk-math display\" data-tex=\"P(X&gt;2)&lt;P(X&gt;1.9)\\approx1-0.8413=0.1587&lt;0.2.\">P(X&gt;2)&lt;P(X&gt;1.9)\\approx1-0.8413=0.1587&lt;0.2.</div> 因此A错误、B正确。<br><br><span class=\"gk-math\" data-tex=\"2=2.1-0.1\">2=2.1-0.1</span>，由正态曲线关于均值对称， <div class=\"gk-math display\" data-tex=\"P(Y&gt;2)=P(Y&lt;2.2)\\approx0.8413.\">P(Y&gt;2)=P(Y&lt;2.2)\\approx0.8413.</div> 因此C正确、D错误。答案为BC。","sourceNote":"","specialNote":"","answerAlternatives":[]},{"id":"2024-new_gaokao_paper_1-q10","paperId":"2024-new_gaokao_paper_1","number":10,"type":"multiple","score":6,"lessonIds":["e2-5.3","3.2"],"difficulty":"进阶","hint":"先把导数化成3(x−1)(x−3)，画出增减表；比较f(x)和f(x²)前，先比较x与x²。","legacy":false,"legacyReason":"","searchText":"设函数 f(x)=(x-1)^2(x-4) ，则（ ） x=3 是 f(x) 的极小值点 当 0<x<1 时， f(x)<f(x^2) 当 1<x<2 时， -4<f(2x-1)<0 当 -1<x<0 时， f(2-x)>f(x)","questionHtml":"设函数 <span class=\"gk-math\" data-tex=\"f(x)=(x-1)^2(x-4)\">f(x)=(x-1)^2(x-4)</span> ，则（ ）","optionsHtml":["<span class=\"gk-math\" data-tex=\"x=3\">x=3</span> 是 <span class=\"gk-math\" data-tex=\"f(x)\">f(x)</span> 的极小值点","当 <span class=\"gk-math\" data-tex=\"0&lt;x&lt;1\">0&lt;x&lt;1</span> 时，<span class=\"gk-math\" data-tex=\"f(x)&lt;f(x^2)\">f(x)&lt;f(x^2)</span>","当 <span class=\"gk-math\" data-tex=\"1&lt;x&lt;2\">1&lt;x&lt;2</span> 时，<span class=\"gk-math\" data-tex=\"-4&lt;f(2x-1)&lt;0\">-4&lt;f(2x-1)&lt;0</span>","当 <span class=\"gk-math\" data-tex=\"-1&lt;x&lt;0\">-1&lt;x&lt;0</span> 时，<span class=\"gk-math\" data-tex=\"f(2-x)&gt;f(x)\">f(2-x)&gt;f(x)</span>"],"answerHtml":"ACD","answerKey":"ACD","solutionHtml":"设 <span class=\"gk-math\" data-tex=\"x\\in\\R\">x\\in\\R</span>， <span class=\"gk-math\" data-tex=\"f&#x27;(x)=3(x-1)(x-3)\">f&#x27;(x)=3(x-1)(x-3)</span>. 当 <span class=\"gk-math\" data-tex=\"x\\in(-\\infty,1)\\cup(3,+\\infty)\">x\\in(-\\infty,1)\\cup(3,+\\infty)</span> 时 <span class=\"gk-math\" data-tex=\"f&#x27;(x)&gt;0\">f&#x27;(x)&gt;0</span>，当 <span class=\"gk-math\" data-tex=\"x\\in(1,3)\">x\\in(1,3)</span> 时 <span class=\"gk-math\" data-tex=\"f&#x27;(x)&lt;0\">f&#x27;(x)&lt;0</span>，故 <span class=\"gk-math\" data-tex=\"x=1\">x=1</span> 是局部极大，<span class=\"gk-math\" data-tex=\"x=3\">x=3</span> 为局部极小；在 <span class=\"gk-math\" data-tex=\"0&lt;x&lt;1\">0&lt;x&lt;1</span> 时 <span class=\"gk-math\" data-tex=\"f\">f</span> 增，故 <span class=\"gk-math\" data-tex=\"f(x)&lt;f(x^2)\">f(x)&lt;f(x^2)</span> 的说法方向相反，<span class=\"gk-math\" data-tex=\"B\">B</span> 错误. 当 <span class=\"gk-math\" data-tex=\"1&lt;x&lt;2\">1&lt;x&lt;2</span> 时，<span class=\"gk-math\" data-tex=\"2x-1\\in(1,3)\">2x-1\\in(1,3)</span> 且 <span class=\"gk-math\" data-tex=\"f\">f</span> 在 <span class=\"gk-math\" data-tex=\"(1,3)\">(1,3)</span> 上递减，所以 <span class=\"gk-math\" data-tex=\"f(1)&gt;f(2x-1)&gt;f(3)\">f(1)&gt;f(2x-1)&gt;f(3)</span>，即 <span class=\"gk-math\" data-tex=\"-4&lt;f(2x-1)&lt;0\">-4&lt;f(2x-1)&lt;0</span>，故 <span class=\"gk-math\" data-tex=\"C\">C</span> 正确. 当 <span class=\"gk-math\" data-tex=\"-1&lt;x&lt;0\">-1&lt;x&lt;0</span>， <span class=\"gk-math\" data-tex=\"f(2-x)-f(x)=2(1-x)^3\">f(2-x)-f(x)=2(1-x)^3</span>. 故 <span class=\"gk-math\" data-tex=\"f(2-x)&gt;f(x)\">f(2-x)&gt;f(x)</span>，所以 D 正确. 故选 ACD.","sourceNote":"","specialNote":"","answerAlternatives":[]},{"id":"2024-new_gaokao_paper_1-q11","paperId":"2024-new_gaokao_paper_1","number":11,"type":"multiple","score":6,"lessonIds":["e1-2.3","3.1"],"difficulty":"挑战","hint":"先把原点代入距离乘积条件求a，再设动点P(x,y)，把两段距离写成坐标式。","legacy":false,"legacyReason":"","searchText":"设计一条美丽的丝带，其造型可以看作图中曲线 C 的一部分。已知 C 过坐标原点 O ，且 C 上的点满足：横坐标大于 -2 ；到点 F(2,0) 的距离与到定直线 x=a （ a<0 ）的距离之积为 4 。则（ ） a=-2 点 (2\\sqrt2,0) 在 C 上 C 在第一象限的点的纵坐标的最大值为 1 当点 (x_0,y_0) 在 C 上时， y_0\\le \\dfrac4{x_0+2}","questionHtml":"设计一条美丽的丝带，其造型可以看作图中曲线 <span class=\"gk-math\" data-tex=\"C\">C</span> 的一部分。已知 <span class=\"gk-math\" data-tex=\"C\">C</span> 过坐标原点 <span class=\"gk-math\" data-tex=\"O\">O</span>，且 <span class=\"gk-math\" data-tex=\"C\">C</span> 上的点满足：横坐标大于 <span class=\"gk-math\" data-tex=\"-2\">-2</span>；到点 <span class=\"gk-math\" data-tex=\"F(2,0)\">F(2,0)</span> 的距离与到定直线 <span class=\"gk-math\" data-tex=\"x=a\">x=a</span>（<span class=\"gk-math\" data-tex=\"a&lt;0\">a&lt;0</span>）的距离之积为 <span class=\"gk-math\" data-tex=\"4\">4</span>。则（ ） <figure class=\"gk-figure\"><button class=\"gk-zoom\" style=\"width:min(100%,626px)\" data-action=\"zoom-image\" data-label=\"高考题图\" data-src=\"./assets/gaokao/figures/2024/new_gaokao_paper_1/q11_fig1.webp\" aria-label=\"放大高考题图\"><img src=\"./assets/gaokao/figures/2024/new_gaokao_paper_1/q11_fig1.webp\" alt=\"高考题图，点击可放大\" width=\"610\" height=\"620\" style=\"aspect-ratio:610/620;width:100%\" loading=\"lazy\"></button></figure>","optionsHtml":["<span class=\"gk-math\" data-tex=\"a=-2\">a=-2</span>","点 <span class=\"gk-math\" data-tex=\"(2\\sqrt2,0)\">(2\\sqrt2,0)</span> 在 <span class=\"gk-math\" data-tex=\"C\">C</span> 上","<span class=\"gk-math\" data-tex=\"C\">C</span> 在第一象限的点的纵坐标的最大值为 <span class=\"gk-math\" data-tex=\"1\">1</span>","当点 <span class=\"gk-math\" data-tex=\"(x_0,y_0)\">(x_0,y_0)</span> 在 <span class=\"gk-math\" data-tex=\"C\">C</span> 上时，<span class=\"gk-math\" data-tex=\"y_0\\le \\dfrac4{x_0+2}\">y_0\\le \\dfrac4{x_0+2}</span>"],"answerHtml":"ABD","answerKey":"ABD","solutionHtml":"设曲线上点为 <span class=\"gk-math\" data-tex=\"P(x,y)\">P(x,y)</span>，则 <span class=\"gk-math\" data-tex=\"x&gt;-2\">x&gt;-2</span> 且 <span class=\"gk-math\" data-tex=\"\\sqrt{(x-2)^2+y^2}\\cdot |x-a|=4\">\\sqrt{(x-2)^2+y^2}\\cdot |x-a|=4</span>. 又 <span class=\"gk-math\" data-tex=\"C\">C</span> 过 <span class=\"gk-math\" data-tex=\"O\">O</span>，代入得 <span class=\"gk-math\" data-tex=\"2\\cdot|0-a|=4\">2\\cdot|0-a|=4</span>，故 <span class=\"gk-math\" data-tex=\"a=-2\">a=-2</span>. 因此曲线方程可写为 <span class=\"gk-math\" data-tex=\"\\sqrt{(x-2)^2+y^2}\\,(x+2)=4\">\\sqrt{(x-2)^2+y^2}\\,(x+2)=4</span>. 两边平方得 <span class=\"gk-math\" data-tex=\"\\left((x-2)^2+y^2\\right)(x+2)^2=16\">\\left((x-2)^2+y^2\\right)(x+2)^2=16</span>. 当 <span class=\"gk-math\" data-tex=\"x=2\\sqrt2\">x=2\\sqrt2</span>，<span class=\"gk-math\" data-tex=\"y=0\">y=0</span> 时， <span class=\"gk-math\" data-tex=\"\\sqrt{(2\\sqrt2-2)^2+0^2}\\,(2\\sqrt2+2)=2(\\sqrt2-1)\\cdot 2(\\sqrt2+1)=4\">\\sqrt{(2\\sqrt2-2)^2+0^2}\\,(2\\sqrt2+2)=2(\\sqrt2-1)\\cdot 2(\\sqrt2+1)=4</span>， 故点 <span class=\"gk-math\" data-tex=\"(2\\sqrt2,0)\">(2\\sqrt2,0)</span> 在 <span class=\"gk-math\" data-tex=\"C\">C</span> 上，<span class=\"gk-math\" data-tex=\"B\">B</span> 正确. 又当 <span class=\"gk-math\" data-tex=\"x=\\frac32\">x=\\frac32</span> 时， <div class=\"gk-math display\" data-tex=\"y^2=\\frac{16}{(x+2)^2}-(x-2)^2=\\frac{64}{49}-\\frac14=\\frac{207}{196}&gt;1\">y^2=\\frac{16}{(x+2)^2}-(x-2)^2=\\frac{64}{49}-\\frac14=\\frac{207}{196}&gt;1</div> 故第一象限上 <span class=\"gk-math\" data-tex=\"y\">y</span> 的最大值大于 <span class=\"gk-math\" data-tex=\"1\">1</span>，所以 <span class=\"gk-math\" data-tex=\"C\">C</span> 错. 再由方程可得 <span class=\"gk-math\" data-tex=\"y_0^2=\\frac{16}{(x_0+2)^2}-(x_0-2)^2\">y_0^2=\\frac{16}{(x_0+2)^2}-(x_0-2)^2</span>. 于是 <span class=\"gk-math\" data-tex=\"y_0^2\\le \\frac{16}{(x_0+2)^2}\">y_0^2\\le \\frac{16}{(x_0+2)^2}</span>. 因为 <span class=\"gk-math\" data-tex=\"x_0+2&gt;0\">x_0+2&gt;0</span>，所以 <span class=\"gk-math\" data-tex=\"y_0\\le \\frac{4}{x_0+2}\">y_0\\le \\frac{4}{x_0+2}</span>. 故 <span class=\"gk-math\" data-tex=\"D\">D</span> 正确.","sourceNote":"","specialNote":"","answerAlternatives":[]},{"id":"2024-new_gaokao_paper_1-q12","paperId":"2024-new_gaokao_paper_1","number":12,"type":"fill","score":5,"lessonIds":["e1-3.2"],"difficulty":"进阶","hint":"利用上下对称先得到AF₂=AB/2=5，再用双曲线距离差求a，用直角三角形求c。","legacy":false,"legacyReason":"","searchText":"设双曲线 C:\\dfrac{x^2}{a^2}-\\dfrac{y^2}{b^2}=1 （ a>0,b>0 ）的左、右焦点分别为 F_1,F_2 ，过 F_2 作平行于 y 轴的直线交 C 于 A,B 两点。若 |F_1A|=13 ， |AB|=10 ，则 C 的离心率为 ________ 。 ","questionHtml":"设双曲线 <span class=\"gk-math\" data-tex=\"C:\\dfrac{x^2}{a^2}-\\dfrac{y^2}{b^2}=1\">C:\\dfrac{x^2}{a^2}-\\dfrac{y^2}{b^2}=1</span>（<span class=\"gk-math\" data-tex=\"a&gt;0,b&gt;0\">a&gt;0,b&gt;0</span>）的左、右焦点分别为 <span class=\"gk-math\" data-tex=\"F_1,F_2\">F_1,F_2</span>，过 <span class=\"gk-math\" data-tex=\"F_2\">F_2</span> 作平行于 <span class=\"gk-math\" data-tex=\"y\">y</span> 轴的直线交 <span class=\"gk-math\" data-tex=\"C\">C</span> 于 <span class=\"gk-math\" data-tex=\"A,B\">A,B</span> 两点。若 <span class=\"gk-math\" data-tex=\"|F_1A|=13\">|F_1A|=13</span>，<span class=\"gk-math\" data-tex=\"|AB|=10\">|AB|=10</span>，则 <span class=\"gk-math\" data-tex=\"C\">C</span> 的离心率为<span class=\"gk-blank\" aria-label=\"填空\">________</span>。 <figure class=\"gk-figure\"><button class=\"gk-zoom\" style=\"width:min(100%,367px)\" data-action=\"zoom-image\" data-label=\"高考题图\" data-src=\"./assets/gaokao/figures/2024/new_gaokao_paper_1/q12_fig1.webp\" aria-label=\"放大高考题图\"><img src=\"./assets/gaokao/figures/2024/new_gaokao_paper_1/q12_fig1.webp\" alt=\"高考题图，点击可放大\" width=\"351\" height=\"376\" style=\"aspect-ratio:351/376;width:100%\" loading=\"lazy\"></button></figure>","optionsHtml":[],"answerHtml":"<span class=\"gk-math\" data-tex=\"\\dfrac{3}{2}\">\\dfrac{3}{2}</span>","answerKey":"","solutionHtml":"由上下对称，<span class=\"gk-math\" data-tex=\"F_2\">F_2</span> 是 <span class=\"gk-math\" data-tex=\"AB\">AB</span> 的中点，所以 <span class=\"gk-math\" data-tex=\"|AF_2|=5\">|AF_2|=5</span>。<br><br>在双曲线右支上，到左、右焦点的距离之差为 <span class=\"gk-math\" data-tex=\"2a\">2a</span>，因此 <div class=\"gk-math display\" data-tex=\"2a=|AF_1|-|AF_2|=13-5=8,\\qquad a=4.\">2a=|AF_1|-|AF_2|=13-5=8,\\qquad a=4.</div> 注意：<span class=\"gk-math\" data-tex=\"2a\">2a</span> 是距离差，两个焦点之间的距离是 <span class=\"gk-math\" data-tex=\"2c\">2c</span>。<br><br>因为 <span class=\"gk-math\" data-tex=\"AF_2\">AF_2</span> 垂直 <span class=\"gk-math\" data-tex=\"F_1F_2\">F_1F_2</span>，在直角三角形 <span class=\"gk-math\" data-tex=\"AF_1F_2\">AF_1F_2</span> 中， <div class=\"gk-math display\" data-tex=\"|F_1F_2|=\\sqrt{13^2-5^2}=12,\\qquad c=6.\">|F_1F_2|=\\sqrt{13^2-5^2}=12,\\qquad c=6.</div> 故离心率 <span class=\"gk-math\" data-tex=\"e=c/a=6/4=3/2\">e=c/a=6/4=3/2</span>。","sourceNote":"","specialNote":"","answerAlternatives":[]},{"id":"2024-new_gaokao_paper_1-q13","paperId":"2024-new_gaokao_paper_1","number":13,"type":"fill","score":5,"lessonIds":["e2-5.1","e2-5.2"],"difficulty":"进阶","hint":"先求第一条曲线在(0,1)的切线y=2x+1，再让第二条曲线在另一切点处的导数等于2。","legacy":false,"legacyReason":"","searchText":"若曲线 y=\\e^x+x 在点 (0,1) 处的切线也是曲线 y=\\ln(x+1)+a 的切线，则 a= ________ 。 ","questionHtml":"若曲线 <span class=\"gk-math\" data-tex=\"y=\\e^x+x\">y=\\e^x+x</span> 在点 <span class=\"gk-math\" data-tex=\"(0,1)\">(0,1)</span> 处的切线也是曲线 <span class=\"gk-math\" data-tex=\"y=\\ln(x+1)+a\">y=\\ln(x+1)+a</span> 的切线，则 <span class=\"gk-math\" data-tex=\"a=\">a=</span><span class=\"gk-blank\" aria-label=\"填空\">________</span>。","optionsHtml":[],"answerHtml":"<span class=\"gk-math\" data-tex=\"\\ln2\">\\ln2</span>","answerKey":"","solutionHtml":"先求第一条曲线在已知切点的切线。因为 <span class=\"gk-math\" data-tex=\"y&#x27;=\\e^x+1\">y&#x27;=\\e^x+1</span>，所以在 <span class=\"gk-math\" data-tex=\"x=0\">x=0</span> 时斜率为 <span class=\"gk-math\" data-tex=\"2\">2</span>，切线为 <span class=\"gk-math\" data-tex=\"y=2x+1\">y=2x+1</span>。<br><br>这条直线与第二条曲线的切点可以不同。设第二个切点横坐标为 <span class=\"gk-math\" data-tex=\"x_0\">x_0</span>。由相同的切线斜率， <div class=\"gk-math display\" data-tex=\"\\frac1{x_0+1}=2,\\qquad x_0=-\\frac12.\">\\frac1{x_0+1}=2,\\qquad x_0=-\\frac12.</div> 切点位于直线 <span class=\"gk-math\" data-tex=\"y=2x+1\">y=2x+1</span> 上，所以其纵坐标为 <span class=\"gk-math\" data-tex=\"0\">0</span>。代入第二条曲线， <div class=\"gk-math display\" data-tex=\"0=\\ln\\frac12+a,\\qquad a=\\ln2.\">0=\\ln\\frac12+a,\\qquad a=\\ln2.</div>","sourceNote":"","specialNote":"","answerAlternatives":[]},{"id":"2024-new_gaokao_paper_1-q14","paperId":"2024-new_gaokao_paper_1","number":14,"type":"fill","score":5,"lessonIds":["e3-6.2","10.1"],"difficulty":"进阶","hint":"可以固定甲的出牌顺序，只列乙的4!种顺序，数出甲至少赢两轮的情况；每轮不是独立抽牌。","legacy":false,"legacyReason":"","searchText":"甲、乙两人各有四张卡片，每张卡片上标有一个数字，甲的卡片上分别标有数字 1,3,5,7 ，乙的卡片上分别标有数字 2,4,6,8 。两人进行四轮比赛。在每轮比赛中，两人各自从自己持有的卡片中随机选一张，并比较所选卡片上数字的大小，数字大的人得 1 分，数字小的人得 0 分，然后各自弃置此轮所选的卡片（弃置的卡片在此后的轮次中不能使用）。则四轮比赛后，甲的总得分不小于 2 的概率为 ________ 。 ","questionHtml":"甲、乙两人各有四张卡片，每张卡片上标有一个数字，甲的卡片上分别标有数字 <span class=\"gk-math\" data-tex=\"1,3,5,7\">1,3,5,7</span>，乙的卡片上分别标有数字 <span class=\"gk-math\" data-tex=\"2,4,6,8\">2,4,6,8</span>。两人进行四轮比赛。在每轮比赛中，两人各自从自己持有的卡片中随机选一张，并比较所选卡片上数字的大小，数字大的人得 <span class=\"gk-math\" data-tex=\"1\">1</span> 分，数字小的人得 <span class=\"gk-math\" data-tex=\"0\">0</span> 分，然后各自弃置此轮所选的卡片（弃置的卡片在此后的轮次中不能使用）。则四轮比赛后，甲的总得分不小于 <span class=\"gk-math\" data-tex=\"2\">2</span> 的概率为<span class=\"gk-blank\" aria-label=\"填空\">________</span>。","optionsHtml":[],"answerHtml":"<span class=\"gk-math\" data-tex=\"\\frac12\">\\frac12</span>","answerKey":"","solutionHtml":"把甲四张卡片的出牌顺序固定，乙的四张卡片按随机顺序依次对应，则共有 <span class=\"gk-math\" data-tex=\"A_4^4=4!\">A_4^4=4!</span> 种等可能结果. 设甲四轮得分分别为 <span class=\"gk-math\" data-tex=\"X_1\">X_1</span>，<span class=\"gk-math\" data-tex=\"X_2\">X_2</span>，<span class=\"gk-math\" data-tex=\"X_3\">X_3</span>，<span class=\"gk-math\" data-tex=\"X_4\">X_4</span>，总分为 <span class=\"gk-math\" data-tex=\"X\">X</span>. 对任意一轮，甲乙两人该轮出示的牌等可能地组成 <span class=\"gk-math\" data-tex=\"16\">16</span> 种有序对，其中甲获胜的有 <span class=\"gk-math\" data-tex=\"6\">6</span> 种，所以 <span class=\"gk-math\" data-tex=\"P(X_k=1)=\\frac{6}{16}=\\frac38\">P(X_k=1)=\\frac{6}{16}=\\frac38</span>（<span class=\"gk-math\" data-tex=\"k=1\">k=1</span>，<span class=\"gk-math\" data-tex=\"2\">2</span>，<span class=\"gk-math\" data-tex=\"3\">3</span>，<span class=\"gk-math\" data-tex=\"4\">4</span>）. 因此 <span class=\"gk-math\" data-tex=\"E(X)=\\sum_{k=1}^4 E(X_k)=4\\times\\frac38=\\frac32\">E(X)=\\sum_{k=1}^4 E(X_k)=4\\times\\frac38=\\frac32</span>. 记 <span class=\"gk-math\" data-tex=\"P(X=j)=p_j\">P(X=j)=p_j</span>（<span class=\"gk-math\" data-tex=\"j=0\">j=0</span>，<span class=\"gk-math\" data-tex=\"1\">1</span>，<span class=\"gk-math\" data-tex=\"2\">2</span>，<span class=\"gk-math\" data-tex=\"3\">3</span>）. 若甲得 <span class=\"gk-math\" data-tex=\"0\">0</span> 分，则只能是甲依次出 <span class=\"gk-math\" data-tex=\"1\">1</span>，<span class=\"gk-math\" data-tex=\"3\">3</span>，<span class=\"gk-math\" data-tex=\"5\">5</span>，<span class=\"gk-math\" data-tex=\"7\">7</span>，乙依次出 <span class=\"gk-math\" data-tex=\"2\">2</span>，<span class=\"gk-math\" data-tex=\"4\">4</span>，<span class=\"gk-math\" data-tex=\"6\">6</span>，<span class=\"gk-math\" data-tex=\"8\">8</span>，故 <span class=\"gk-math\" data-tex=\"p_0=\\frac1{24}\">p_0=\\frac1{24}</span>. 若甲得 <span class=\"gk-math\" data-tex=\"3\">3</span> 分，则只能是甲依次出 <span class=\"gk-math\" data-tex=\"1\">1</span>，<span class=\"gk-math\" data-tex=\"3\">3</span>，<span class=\"gk-math\" data-tex=\"5\">5</span>，<span class=\"gk-math\" data-tex=\"7\">7</span>，乙依次出 <span class=\"gk-math\" data-tex=\"8\">8</span>，<span class=\"gk-math\" data-tex=\"2\">2</span>，<span class=\"gk-math\" data-tex=\"4\">4</span>，<span class=\"gk-math\" data-tex=\"6\">6</span>，故 <span class=\"gk-math\" data-tex=\"p_3=\\frac1{24}\">p_3=\\frac1{24}</span>. 又因为 <span class=\"gk-math\" data-tex=\"X\">X</span> 的所有可能取值为 <span class=\"gk-math\" data-tex=\"0\">0</span>，<span class=\"gk-math\" data-tex=\"1\">1</span>，<span class=\"gk-math\" data-tex=\"2\">2</span>，<span class=\"gk-math\" data-tex=\"3\">3</span>，所以 <span class=\"gk-math\" data-tex=\"p_0+p_1+p_2+p_3=1\">p_0+p_1+p_2+p_3=1</span>， <span class=\"gk-math\" data-tex=\"p_1+2p_2+3p_3=E(X)=\\frac32\">p_1+2p_2+3p_3=E(X)=\\frac32</span>. 代入 <span class=\"gk-math\" data-tex=\"p_0=\\frac1{24}\">p_0=\\frac1{24}</span>，<span class=\"gk-math\" data-tex=\"p_3=\\frac1{24}\">p_3=\\frac1{24}</span> 得 <span class=\"gk-math\" data-tex=\"p_1+p_2=\\frac{11}{12}\">p_1+p_2=\\frac{11}{12}</span>，<span class=\"gk-math\" data-tex=\"p_1+2p_2=\\frac{11}{8}\">p_1+2p_2=\\frac{11}{8}</span>， 解得 <span class=\"gk-math\" data-tex=\"p_2=\\frac{11}{24}\">p_2=\\frac{11}{24}</span>. 因此 <div class=\"gk-math display\" data-tex=\"P(X\\ge2)=p_2+p_3=\\frac{11}{24}+\\frac1{24}=\\frac12\">P(X\\ge2)=p_2+p_3=\\frac{11}{24}+\\frac1{24}=\\frac12</div> 故所求概率为 <span class=\"gk-math\" data-tex=\"\\frac12\">\\frac12</span>.","sourceNote":"","specialNote":"","answerAlternatives":[]},{"id":"2024-new_gaokao_paper_1-q15","paperId":"2024-new_gaokao_paper_1","number":15,"type":"written","score":13,"lessonIds":["6.4","5.5"],"difficulty":"进阶","hint":"先把a²+b²−c²与余弦定理对照求C，再用sinC=√2cosB确定B，最后用面积公式求边长。","legacy":false,"legacyReason":"","searchText":"记 \\triangle ABC 的内角 A,B,C 的对边分别为 a,b,c 。已知 \\sin C=\\sqrt2\\cos B ， a^2+b^2-c^2=\\sqrt2ab 。 求 B ； 若 \\triangle ABC 的面积为 3+\\sqrt3 ，求 c 。 ","questionHtml":"记 <span class=\"gk-math\" data-tex=\"\\triangle ABC\">\\triangle ABC</span> 的内角 <span class=\"gk-math\" data-tex=\"A,B,C\">A,B,C</span> 的对边分别为 <span class=\"gk-math\" data-tex=\"a,b,c\">a,b,c</span>。已知 <span class=\"gk-math\" data-tex=\"\\sin C=\\sqrt2\\cos B\">\\sin C=\\sqrt2\\cos B</span>，<span class=\"gk-math\" data-tex=\"a^2+b^2-c^2=\\sqrt2ab\">a^2+b^2-c^2=\\sqrt2ab</span>。 <ol class=\"gk-subparts\"><li>求 <span class=\"gk-math\" data-tex=\"B\">B</span>；</li><li>若 <span class=\"gk-math\" data-tex=\"\\triangle ABC\">\\triangle ABC</span> 的面积为 <span class=\"gk-math\" data-tex=\"3+\\sqrt3\">3+\\sqrt3</span>，求 <span class=\"gk-math\" data-tex=\"c\">c</span>。</li></ol>","optionsHtml":[],"answerHtml":"<span>见下方分步解析</span>","answerKey":"","solutionHtml":"<ol class=\"gk-subparts\"><li>由余弦定理，<span class=\"gk-math\" data-tex=\"a^2+b^2-c^2=2ab\\cos C\">a^2+b^2-c^2=2ab\\cos C</span>。与已知条件比较，得 <span class=\"gk-math\" data-tex=\"\\cos C=\\sqrt2/2\">\\cos C=\\sqrt2/2</span>。因为 <span class=\"gk-math\" data-tex=\"C\">C</span> 是三角形内角，所以 <span class=\"gk-math\" data-tex=\"C=\\pi/4\">C=\\pi/4</span>，<span class=\"gk-math\" data-tex=\"\\sin C=\\sqrt2/2\">\\sin C=\\sqrt2/2</span>。代入 <span class=\"gk-math\" data-tex=\"\\sin C=\\sqrt2\\cos B\">\\sin C=\\sqrt2\\cos B</span>，得 <span class=\"gk-math\" data-tex=\"\\cos B=1/2\">\\cos B=1/2</span>，因此 <span class=\"gk-math\" data-tex=\"B=\\pi/3\">B=\\pi/3</span>。</li><li>内角和给出 <span class=\"gk-math\" data-tex=\"A=5\\pi/12\">A=5\\pi/12</span>。由正弦定理， <div class=\"gk-math display\" data-tex=\"a=\\frac{\\sin A}{\\sin C}c=\\frac{\\sqrt3+1}{2}c,\\qquad\nb=\\frac{\\sin B}{\\sin C}c=\\frac{\\sqrt6}{2}c.\">a=\\frac{\\sin A}{\\sin C}c=\\frac{\\sqrt3+1}{2}c,\\qquad\nb=\\frac{\\sin B}{\\sin C}c=\\frac{\\sqrt6}{2}c.</div> 所以 <div class=\"gk-math display\" data-tex=\"S=\\frac12ab\\sin C=\\frac{3+\\sqrt3}{8}c^2.\">S=\\frac12ab\\sin C=\\frac{3+\\sqrt3}{8}c^2.</div> 代入 <span class=\"gk-math\" data-tex=\"S=3+\\sqrt3\">S=3+\\sqrt3</span>，得 <span class=\"gk-math\" data-tex=\"c^2=8\">c^2=8</span>，故 <span class=\"gk-math\" data-tex=\"c=2\\sqrt2\">c=2\\sqrt2</span>。</li></ol>","sourceNote":"","specialNote":"","answerAlternatives":[]},{"id":"2024-new_gaokao_paper_1-q16","paperId":"2024-new_gaokao_paper_1","number":16,"type":"written","score":15,"lessonIds":["e1-3.1","e1-2.3"],"difficulty":"进阶","hint":"先将A、P代入椭圆求a²、b²；第二问先求AP长，把面积9换成B到直线AP的距离。","legacy":false,"legacyReason":"","searchText":"已知 A(0,3) ， P\\left(3,\\frac32\\right) 都在椭圆 C:\\frac{x^2}{a^2}+\\frac{y^2}{b^2}=1 （ a>b>0 ） 上. 求 C 的离心率； 过 P 的直线 l 交 C 于另一点 B ，且 \\triangle ABP 的面积为 9 ，求 l 的方程. ","questionHtml":"已知 <span class=\"gk-math\" data-tex=\"A(0,3)\">A(0,3)</span>，<span class=\"gk-math\" data-tex=\"P\\left(3,\\frac32\\right)\">P\\left(3,\\frac32\\right)</span> 都在椭圆 <span class=\"gk-math\" data-tex=\"C:\\frac{x^2}{a^2}+\\frac{y^2}{b^2}=1\">C:\\frac{x^2}{a^2}+\\frac{y^2}{b^2}=1</span>（<span class=\"gk-math\" data-tex=\"a&gt;b&gt;0\">a&gt;b&gt;0</span>） 上. <ol class=\"gk-subparts\"><li>求 <span class=\"gk-math\" data-tex=\"C\">C</span> 的离心率；</li><li>过 <span class=\"gk-math\" data-tex=\"P\">P</span> 的直线 <span class=\"gk-math\" data-tex=\"l\">l</span> 交 <span class=\"gk-math\" data-tex=\"C\">C</span> 于另一点 <span class=\"gk-math\" data-tex=\"B\">B</span>，且 <span class=\"gk-math\" data-tex=\"\\triangle ABP\">\\triangle ABP</span> 的面积为 <span class=\"gk-math\" data-tex=\"9\">9</span>，求 <span class=\"gk-math\" data-tex=\"l\">l</span> 的方程.</li></ol>","optionsHtml":[],"answerHtml":"<span>见下方分步解析</span>","answerKey":"","solutionHtml":"<ol class=\"gk-subparts\"><li>由 <span class=\"gk-math\" data-tex=\"A(0,3)\\in C\">A(0,3)\\in C</span> 得 <span class=\"gk-math\" data-tex=\"\\frac{3^2}{b^2}=1\">\\frac{3^2}{b^2}=1</span>， 所以 <span class=\"gk-math\" data-tex=\"b^2=9\">b^2=9</span>. 再将 <span class=\"gk-math\" data-tex=\"P\\left(3,\\frac32\\right)\\in C\">P\\left(3,\\frac32\\right)\\in C</span> 代入得 <span class=\"gk-math\" data-tex=\"\\frac{3^2}{a^2}+\\frac{(\\frac{3}{2})^2}{9}=1 \\Rightarrow \\frac{9}{a^2}+\\frac14=1 \\Rightarrow a^2=12\">\\frac{3^2}{a^2}+\\frac{(\\frac{3}{2})^2}{9}=1 \\Rightarrow \\frac{9}{a^2}+\\frac14=1 \\Rightarrow a^2=12</span>. 故离心率 <span class=\"gk-math\" data-tex=\"e=\\sqrt{1-\\frac{b^2}{a^2}}=\\sqrt{1-\\frac{9}{12}}=\\frac12\">e=\\sqrt{1-\\frac{b^2}{a^2}}=\\sqrt{1-\\frac{9}{12}}=\\frac12</span>.</li><li>直线 <span class=\"gk-math\" data-tex=\"AP\">AP</span> 的方程为 <span class=\"gk-math\" data-tex=\"y=-\\frac12x+3\">y=-\\frac12x+3</span>， 即 <span class=\"gk-math\" data-tex=\"x+2y-6=0\">x+2y-6=0</span>. 设直线 <span class=\"gk-math\" data-tex=\"l\">l</span> 与椭圆交于另一点 <span class=\"gk-math\" data-tex=\"B\">B</span>. 由面积公式 <span class=\"gk-math\" data-tex=\"S_{\\triangle ABP}=9\">S_{\\triangle ABP}=9</span> 得点 <span class=\"gk-math\" data-tex=\"B\">B</span> 到直线 <span class=\"gk-math\" data-tex=\"AP\">AP</span> 的距离为 <span class=\"gk-math\" data-tex=\"\\frac{2S_{\\triangle ABP}}{|AP|}=\\frac{18}{\\frac{3\\sqrt5}{2}}=\\frac{12}{\\sqrt5}\">\\frac{2S_{\\triangle ABP}}{|AP|}=\\frac{18}{\\frac{3\\sqrt5}{2}}=\\frac{12}{\\sqrt5}</span>. 设 <span class=\"gk-math\" data-tex=\"B(x_0,y_0)\">B(x_0,y_0)</span>. 联立 <span class=\"gk-math\" data-tex=\"\\frac{x_0^2}{12}+\\frac{y_0^2}{9}=1\">\\frac{x_0^2}{12}+\\frac{y_0^2}{9}=1</span> 及点到直线 <span class=\"gk-math\" data-tex=\"x+2y-6=0\">x+2y-6=0</span> 的距离公式 <span class=\"gk-math\" data-tex=\"\\frac{|x_0+2y_0-6|}{\\sqrt5}=\\frac{12}{\\sqrt5}\">\\frac{|x_0+2y_0-6|}{\\sqrt5}=\\frac{12}{\\sqrt5}</span>， 解得 <span class=\"gk-math\" data-tex=\"B=(0,-3)\">B=(0,-3)</span>或<span class=\"gk-math\" data-tex=\"B=\\left(-3,-\\frac32\\right)\">B=\\left(-3,-\\frac32\\right)</span>. 于是过 <span class=\"gk-math\" data-tex=\"P\">P</span> 与这两个点的直线分别为 <span class=\"gk-math\" data-tex=\"3x-2y-6=0\">3x-2y-6=0</span>，<span class=\"gk-math\" data-tex=\"x-2y=0\">x-2y=0</span>.</li></ol>","sourceNote":"","specialNote":"","answerAlternatives":[]},{"id":"2024-new_gaokao_paper_1-q17","paperId":"2024-new_gaokao_paper_1","number":17,"type":"written","score":15,"lessonIds":["8.6","8.5","e1-1.4"],"difficulty":"挑战","hint":"先由AB²+BC²=AC²找出直角；第一问用AD同时垂直PA、PB推出AD垂直平面PAB。","legacy":false,"legacyReason":"","searchText":"如图，四棱锥 P-ABCD 中， PA\\perp 底面 ABCD ，且 PA=AC=2 ， BC=1 ， AB=\\sqrt3 . 若 AD\\perp PB ，证明 AD\\parallel 平面 PBC ； 若 AD\\perp DC ，且二面角 A-CP-D 的正弦值为 \\frac{\\sqrt{42}}{7} ，求 AD . ","questionHtml":"如图，四棱锥 <span class=\"gk-math\" data-tex=\"P-ABCD\">P-ABCD</span> 中，<span class=\"gk-math\" data-tex=\"PA\\perp\">PA\\perp</span> 底面 <span class=\"gk-math\" data-tex=\"ABCD\">ABCD</span>，且 <span class=\"gk-math\" data-tex=\"PA=AC=2\">PA=AC=2</span>，<span class=\"gk-math\" data-tex=\"BC=1\">BC=1</span>，<span class=\"gk-math\" data-tex=\"AB=\\sqrt3\">AB=\\sqrt3</span>.<br><br><ol class=\"gk-subparts\"><li>若 <span class=\"gk-math\" data-tex=\"AD\\perp PB\">AD\\perp PB</span>，证明 <span class=\"gk-math\" data-tex=\"AD\\parallel\">AD\\parallel</span> 平面 <span class=\"gk-math\" data-tex=\"PBC\">PBC</span>；</li><li>若 <span class=\"gk-math\" data-tex=\"AD\\perp DC\">AD\\perp DC</span>，且二面角 <span class=\"gk-math\" data-tex=\"A-CP-D\">A-CP-D</span> 的正弦值为 <span class=\"gk-math\" data-tex=\"\\frac{\\sqrt{42}}{7}\">\\frac{\\sqrt{42}}{7}</span>，求 <span class=\"gk-math\" data-tex=\"AD\">AD</span>.</li></ol><br><br><figure class=\"gk-figure\"><button class=\"gk-zoom\" style=\"width:min(100%,469px)\" data-action=\"zoom-image\" data-label=\"高考题图\" data-src=\"./assets/gaokao/figures/2024/new_gaokao_paper_1/q17_fig1.webp\" aria-label=\"放大高考题图\"><img src=\"./assets/gaokao/figures/2024/new_gaokao_paper_1/q17_fig1.webp\" alt=\"高考题图，点击可放大\" width=\"453\" height=\"518\" style=\"aspect-ratio:453/518;width:100%\" loading=\"lazy\"></button></figure>","optionsHtml":[],"answerHtml":"<span>见下方分步解析</span>","answerKey":"","solutionHtml":"<ol class=\"gk-subparts\"><li>因为 <span class=\"gk-math\" data-tex=\"PA\\perp\">PA\\perp</span> 底面 <span class=\"gk-math\" data-tex=\"ABCD\">ABCD</span>，且 <span class=\"gk-math\" data-tex=\"AD\\subset\">AD\\subset</span> 底面 <span class=\"gk-math\" data-tex=\"ABCD\">ABCD</span>，故 <span class=\"gk-math\" data-tex=\"PA\\perp AD\">PA\\perp AD</span>. 已知 <span class=\"gk-math\" data-tex=\"AD\\perp PB\">AD\\perp PB</span>，又 <span class=\"gk-math\" data-tex=\"PA\">PA</span>，<span class=\"gk-math\" data-tex=\"PB\">PB</span> 是平面 <span class=\"gk-math\" data-tex=\"PAB\">PAB</span> 内两条相交直线，所以 <span class=\"gk-math\" data-tex=\"AD\\perp\">AD\\perp</span> 平面 <span class=\"gk-math\" data-tex=\"PAB\">PAB</span>. 因此 <span class=\"gk-math\" data-tex=\"AD\\perp AB\">AD\\perp AB</span>. 又由 <span class=\"gk-math\" data-tex=\"AC^2=AB^2+BC^2\">AC^2=AB^2+BC^2</span> 由勾股定理逆定理得 <span class=\"gk-math\" data-tex=\"\\triangle ABC\">\\triangle ABC</span> 是以 <span class=\"gk-math\" data-tex=\"B\">B</span> 为直角的直角三角形，从而 <span class=\"gk-math\" data-tex=\"AB\\perp BC\">AB\\perp BC</span>. 因为 <span class=\"gk-math\" data-tex=\"AD\">AD</span>，<span class=\"gk-math\" data-tex=\"BC\">BC</span> 都在底面 <span class=\"gk-math\" data-tex=\"ABCD\">ABCD</span> 内，且都垂直于 <span class=\"gk-math\" data-tex=\"AB\">AB</span>，所以 <span class=\"gk-math\" data-tex=\"AD\\parallel BC\">AD\\parallel BC</span>. 又 <span class=\"gk-math\" data-tex=\"BC\\subset\">BC\\subset</span> 平面 <span class=\"gk-math\" data-tex=\"PBC\">PBC</span>，故 <span class=\"gk-math\" data-tex=\"AD\\parallel\">AD\\parallel</span> 平面 <span class=\"gk-math\" data-tex=\"PBC\">PBC</span>.</li><li>由 <span class=\"gk-math\" data-tex=\"AD\\perp DC\">AD\\perp DC</span> 且 <span class=\"gk-math\" data-tex=\"AC=2\">AC=2</span>，设 <span class=\"gk-math\" data-tex=\"AD=x\">AD=x</span>，则 <span class=\"gk-math\" data-tex=\"CD=\\sqrt{4-x^2}\">CD=\\sqrt{4-x^2}</span>. 过点 <span class=\"gk-math\" data-tex=\"D\">D</span> 作 <span class=\"gk-math\" data-tex=\"DE\\perp AC\">DE\\perp AC</span> 于 <span class=\"gk-math\" data-tex=\"E\">E</span>，再过点 <span class=\"gk-math\" data-tex=\"E\">E</span> 作 <span class=\"gk-math\" data-tex=\"EF\\perp CP\">EF\\perp CP</span> 于 <span class=\"gk-math\" data-tex=\"F\">F</span>，连接 <span class=\"gk-math\" data-tex=\"DF\">DF</span>. <figure class=\"gk-figure\"><button class=\"gk-zoom\" style=\"width:min(100%,376px)\" data-action=\"zoom-image\" data-label=\"高考题图\" data-src=\"./assets/gaokao/figures/2024/new_gaokao_paper_1/q17_solution_fig1.webp\" aria-label=\"放大高考题图\"><img src=\"./assets/gaokao/figures/2024/new_gaokao_paper_1/q17_solution_fig1.webp\" alt=\"高考题图，点击可放大\" width=\"360\" height=\"445\" style=\"aspect-ratio:360/445;width:100%\" loading=\"lazy\"></button></figure> 因为 <span class=\"gk-math\" data-tex=\"PA\\perp\">PA\\perp</span> 底面 <span class=\"gk-math\" data-tex=\"ABCD\">ABCD</span>，所以平面 <span class=\"gk-math\" data-tex=\"PAC\\perp\">PAC\\perp</span> 平面 <span class=\"gk-math\" data-tex=\"ABCD\">ABCD</span>，且它们的交线为 <span class=\"gk-math\" data-tex=\"AC\">AC</span>. 由 <span class=\"gk-math\" data-tex=\"DE\\perp AC\">DE\\perp AC</span> 且 <span class=\"gk-math\" data-tex=\"DE\\subset\">DE\\subset</span> 平面 <span class=\"gk-math\" data-tex=\"ABCD\">ABCD</span>，得 <span class=\"gk-math\" data-tex=\"DE\\perp\">DE\\perp</span> 平面 <span class=\"gk-math\" data-tex=\"PAC\">PAC</span>. 又 <span class=\"gk-math\" data-tex=\"EF\\perp CP\">EF\\perp CP</span>，而 <span class=\"gk-math\" data-tex=\"CP\\subset\">CP\\subset</span> 平面 <span class=\"gk-math\" data-tex=\"PAC\">PAC</span>，所以 <span class=\"gk-math\" data-tex=\"CP\\perp\">CP\\perp</span> 平面 <span class=\"gk-math\" data-tex=\"DEF\">DEF</span>. 因此 <span class=\"gk-math\" data-tex=\"\\angle DFE\">\\angle DFE</span> 为二面角 <span class=\"gk-math\" data-tex=\"A-CP-D\">A-CP-D</span> 的平面角. 已知 <span class=\"gk-math\" data-tex=\"\\sin\\angle DFE=\\frac{\\sqrt{42}}{7}\">\\sin\\angle DFE=\\frac{\\sqrt{42}}{7}</span>， 故 <span class=\"gk-math\" data-tex=\"\\tan\\angle DFE=\\sqrt6\">\\tan\\angle DFE=\\sqrt6</span>. 由等面积关系可得 <span class=\"gk-math\" data-tex=\"DE=\\frac{x\\sqrt{4-x^2}}{2}\">DE=\\frac{x\\sqrt{4-x^2}}{2}</span>. 又 <div class=\"gk-math display\" data-tex=\"CE=\\sqrt{CD^2-DE^2}=\\sqrt{(4-x^2)-\\frac{x^2(4-x^2)}{4}}=\\frac{4-x^2}{2}\">CE=\\sqrt{CD^2-DE^2}=\\sqrt{(4-x^2)-\\frac{x^2(4-x^2)}{4}}=\\frac{4-x^2}{2}</div> 在 <span class=\"gk-math\" data-tex=\"\\triangle PAC\">\\triangle PAC</span> 中，<span class=\"gk-math\" data-tex=\"PA=AC=2\">PA=AC=2</span>，且 <span class=\"gk-math\" data-tex=\"PA\\perp AC\">PA\\perp AC</span>，所以 <span class=\"gk-math\" data-tex=\"\\angle ACP=\\frac{\\pi}{4}\">\\angle ACP=\\frac{\\pi}{4}</span>. 又 <span class=\"gk-math\" data-tex=\"CE\\subset AC\">CE\\subset AC</span>，<span class=\"gk-math\" data-tex=\"CF\\subset CP\">CF\\subset CP</span>，故 <span class=\"gk-math\" data-tex=\"\\angle ECF=\\frac{\\pi}{4}\">\\angle ECF=\\frac{\\pi}{4}</span>. 因为 <span class=\"gk-math\" data-tex=\"EF\\perp CP\">EF\\perp CP</span>，所以 <span class=\"gk-math\" data-tex=\"\\angle EFC=\\frac{\\pi}{2}\">\\angle EFC=\\frac{\\pi}{2}</span>，从而 <span class=\"gk-math\" data-tex=\"\\triangle EFC\">\\triangle EFC</span> 是等腰直角三角形，所以 <span class=\"gk-math\" data-tex=\"EF=\\frac{CE}{\\sqrt2}=\\frac{4-x^2}{2\\sqrt2}\">EF=\\frac{CE}{\\sqrt2}=\\frac{4-x^2}{2\\sqrt2}</span>. 因此 <div class=\"gk-math display\" data-tex=\"\\tan\\angle DFE=\\frac{DE}{EF}=\\frac{\\frac{x\\sqrt{4-x^2}}{2}}{\\frac{4-x^2}{2\\sqrt2}}=\\frac{x\\sqrt2}{\\sqrt{4-x^2}}=\\sqrt6\">\\tan\\angle DFE=\\frac{DE}{EF}=\\frac{\\frac{x\\sqrt{4-x^2}}{2}}{\\frac{4-x^2}{2\\sqrt2}}=\\frac{x\\sqrt2}{\\sqrt{4-x^2}}=\\sqrt6</div> 解得 <span class=\"gk-math\" data-tex=\"x^2=3\">x^2=3</span>. 故 <span class=\"gk-math\" data-tex=\"AD=x=\\sqrt3\">AD=x=\\sqrt3</span>.</li></ol>","sourceNote":"","specialNote":"","answerAlternatives":[]},{"id":"2024-new_gaokao_paper_1-q18","paperId":"2024-new_gaokao_paper_1","number":18,"type":"written","score":17,"lessonIds":["e2-5.3","3.2"],"difficulty":"挑战","hint":"第一问先求导并观察x(2−x)的最大值；证明中心对称时，直接计算f(x)+f(2−x)。","legacy":false,"legacyReason":"","searchText":"已知函数 f(x)=\\ln\\dfrac{x}{2-x}+ax+b(x-1)^3 。 若 b=0 ，且 f'(x)\\ge0 ，求 a 的最小值； 证明：曲线 y=f(x) 是中心对称图形； 若 f(x)>-2 当且仅当 1<x<2 ，求 b 的取值范围。 ","questionHtml":"已知函数 <span class=\"gk-math\" data-tex=\"f(x)=\\ln\\dfrac{x}{2-x}+ax+b(x-1)^3\">f(x)=\\ln\\dfrac{x}{2-x}+ax+b(x-1)^3</span>。 <ol class=\"gk-subparts\"><li>若 <span class=\"gk-math\" data-tex=\"b=0\">b=0</span>，且 <span class=\"gk-math\" data-tex=\"f&#x27;(x)\\ge0\">f&#x27;(x)\\ge0</span>，求 <span class=\"gk-math\" data-tex=\"a\">a</span> 的最小值；</li><li>证明：曲线 <span class=\"gk-math\" data-tex=\"y=f(x)\">y=f(x)</span> 是中心对称图形；</li><li>若 <span class=\"gk-math\" data-tex=\"f(x)&gt;-2\">f(x)&gt;-2</span> 当且仅当 <span class=\"gk-math\" data-tex=\"1&lt;x&lt;2\">1&lt;x&lt;2</span>，求 <span class=\"gk-math\" data-tex=\"b\">b</span> 的取值范围。</li></ol>","optionsHtml":[],"answerHtml":"<span>见下方分步解析</span>","answerKey":"","solutionHtml":"函数的定义域是 <span class=\"gk-math\" data-tex=\"(0,2)\">(0,2)</span>。 <ol class=\"gk-subparts\"><li>当 <span class=\"gk-math\" data-tex=\"b=0\">b=0</span> 时， <div class=\"gk-math display\" data-tex=\"f&#x27;(x)=\\frac2{x(2-x)}+a.\">f&#x27;(x)=\\frac2{x(2-x)}+a.</div> 因为 <span class=\"gk-math\" data-tex=\"0&lt;x(2-x)\\le1\">0&lt;x(2-x)\\le1</span>，所以分式的最小值为 <span class=\"gk-math\" data-tex=\"2\">2</span>，在 <span class=\"gk-math\" data-tex=\"x=1\">x=1</span> 取得。要使整个定义域内 <span class=\"gk-math\" data-tex=\"f&#x27;(x)\\ge0\">f&#x27;(x)\\ge0</span>，等价于 <span class=\"gk-math\" data-tex=\"a+2\\ge0\">a+2\\ge0</span>，故 <span class=\"gk-math\" data-tex=\"a\">a</span> 的最小值为 <span class=\"gk-math\" data-tex=\"-2\">-2</span>。</li><li>直接计算得 <div class=\"gk-math display\" data-tex=\"f(2-x)=2a-f(x),\\qquad x\\in(0,2).\">f(2-x)=2a-f(x),\\qquad x\\in(0,2).</div> 每个点 <span class=\"gk-math\" data-tex=\"(x,f(x))\">(x,f(x))</span> 都对应图像上的点 <span class=\"gk-math\" data-tex=\"(2-x,2a-f(x))\">(2-x,2a-f(x))</span>，二者的中点都是 <span class=\"gk-math\" data-tex=\"(1,a)\">(1,a)</span>，所以图像关于 <span class=\"gk-math\" data-tex=\"(1,a)\">(1,a)</span> 中心对称。</li><li>由“当且仅当”可知，<span class=\"gk-math\" data-tex=\"x&gt;1\">x&gt;1</span> 一侧有 <span class=\"gk-math\" data-tex=\"f(x)&gt;-2\">f(x)&gt;-2</span>，<span class=\"gk-math\" data-tex=\"x\\le1\">x\\le1</span> 一侧有 <span class=\"gk-math\" data-tex=\"f(x)\\le-2\">f(x)\\le-2</span>。利用在 <span class=\"gk-math\" data-tex=\"1\">1</span> 处连续，得到 <span class=\"gk-math\" data-tex=\"f(1)=-2\">f(1)=-2</span>，从而 <span class=\"gk-math\" data-tex=\"a=-2\">a=-2</span>。<br><br>令 <span class=\"gk-math\" data-tex=\"t=x-1\">t=x-1</span>，并记 <div class=\"gk-math display\" data-tex=\"g(t)=\\ln\\frac{1+t}{1-t}-2t+bt^3,\\qquad -1&lt;t&lt;1.\">g(t)=\\ln\\frac{1+t}{1-t}-2t+bt^3,\\qquad -1&lt;t&lt;1.</div> 这是奇函数，且 <span class=\"gk-math\" data-tex=\"f(x)+2=g(t)\">f(x)+2=g(t)</span>。所以只需保证 <span class=\"gk-math\" data-tex=\"0&lt;t&lt;1\">0&lt;t&lt;1</span> 时 <span class=\"gk-math\" data-tex=\"g(t)&gt;0\">g(t)&gt;0</span>。 <div class=\"gk-math display\" data-tex=\"g&#x27;(t)=\\frac{t^2[\\,2+3b(1-t^2)\\,]}{1-t^2}.\">g&#x27;(t)=\\frac{t^2[\\,2+3b(1-t^2)\\,]}{1-t^2}.</div> 当 <span class=\"gk-math\" data-tex=\"b\\ge0\">b\\ge0</span> 时，括号为正；当 <span class=\"gk-math\" data-tex=\"-2/3\\le b&lt;0\">-2/3\\le b&lt;0</span> 时，<span class=\"gk-math\" data-tex=\"2+3b(1-t^2)&gt;2+3b\\ge0\">2+3b(1-t^2)&gt;2+3b\\ge0</span>。因此 <span class=\"gk-math\" data-tex=\"b\\ge-2/3\">b\\ge-2/3</span> 时，<span class=\"gk-math\" data-tex=\"g\">g</span> 在 <span class=\"gk-math\" data-tex=\"(0,1)\">(0,1)</span> 严格递增，<span class=\"gk-math\" data-tex=\"g(t)&gt;g(0)=0\">g(t)&gt;g(0)=0</span>。<br><br>若 <span class=\"gk-math\" data-tex=\"b&lt;-2/3\">b&lt;-2/3</span>，括号在 <span class=\"gk-math\" data-tex=\"t=0\">t=0</span> 时小于0，由连续性，它在某个足够小的正区间仍小于0。因此 <span class=\"gk-math\" data-tex=\"g\">g</span> 从 <span class=\"gk-math\" data-tex=\"g(0)=0\">g(0)=0</span> 开始递减，出现 <span class=\"gk-math\" data-tex=\"g(t)&lt;0\">g(t)&lt;0</span>，不符合题意。故 <span class=\"gk-math\" data-tex=\"b\\in[-2/3,+\\infty)\">b\\in[-2/3,+\\infty)</span>。</li></ol>","sourceNote":"","specialNote":"","answerAlternatives":[]},{"id":"2024-new_gaokao_paper_1-q19","paperId":"2024-new_gaokao_paper_1","number":19,"type":"written","score":17,"lessonIds":["e2-4.2","e3-6.2","10.1"],"difficulty":"挑战","hint":"先把等差数列换成下标1到4m+2来研究，从m=1时删掉两个数后还能留下四项等差开始。","legacy":false,"legacyReason":"","searchText":"设 m 为正整数，数列 a_1 ， a_2 ， \\dots ， a_{4m+2} 为公差不为 0 的等差数列，若删去两项 a_i ， a_j （ i<j ） 后剩余 4m 项可平均分为 m 组且每组 4 个数都成等差，则称该数列为 (i,j) -可分数列. 写出所有 (i,j) ， 1\\le i<j\\le6 ，使 a_1 ， \\dots ， a_6 是 (i,j) -可分数列； 当 m\\ge3 时，证明 a_1 ， \\dots ， a_{4m+2} 是 (2,13) -可分数列； 从 1 ， 2 ， \\dots ， 4m+2 中不放回任取 i<j ，设 a_1 ， \\dots ， a_{4m+2} 是 (i,j) -可分数列的概率为 P_m ，证明 P_m>\\frac18 . ","questionHtml":"设 <span class=\"gk-math\" data-tex=\"m\">m</span> 为正整数，数列 <span class=\"gk-math\" data-tex=\"a_1\">a_1</span>，<span class=\"gk-math\" data-tex=\"a_2\">a_2</span>，<span class=\"gk-math\" data-tex=\"\\dots\">\\dots</span>，<span class=\"gk-math\" data-tex=\"a_{4m+2}\">a_{4m+2}</span> 为公差不为 <span class=\"gk-math\" data-tex=\"0\">0</span> 的等差数列，若删去两项 <span class=\"gk-math\" data-tex=\"a_i\">a_i</span>，<span class=\"gk-math\" data-tex=\"a_j\">a_j</span>（<span class=\"gk-math\" data-tex=\"i&lt;j\">i&lt;j</span>） 后剩余 <span class=\"gk-math\" data-tex=\"4m\">4m</span> 项可平均分为 <span class=\"gk-math\" data-tex=\"m\">m</span> 组且每组 4 个数都成等差，则称该数列为 <span class=\"gk-math\" data-tex=\"(i,j)\">(i,j)</span>-可分数列. <ol class=\"gk-subparts\"><li>写出所有 <span class=\"gk-math\" data-tex=\"(i,j)\">(i,j)</span>，<span class=\"gk-math\" data-tex=\"1\\le i&lt;j\\le6\">1\\le i&lt;j\\le6</span>，使 <span class=\"gk-math\" data-tex=\"a_1\">a_1</span>，<span class=\"gk-math\" data-tex=\"\\dots\">\\dots</span>，<span class=\"gk-math\" data-tex=\"a_6\">a_6</span> 是 <span class=\"gk-math\" data-tex=\"(i,j)\">(i,j)</span>-可分数列；</li><li>当 <span class=\"gk-math\" data-tex=\"m\\ge3\">m\\ge3</span> 时，证明 <span class=\"gk-math\" data-tex=\"a_1\">a_1</span>，<span class=\"gk-math\" data-tex=\"\\dots\">\\dots</span>，<span class=\"gk-math\" data-tex=\"a_{4m+2}\">a_{4m+2}</span> 是 <span class=\"gk-math\" data-tex=\"(2,13)\">(2,13)</span>-可分数列；</li><li>从 <span class=\"gk-math\" data-tex=\"1\">1</span>，<span class=\"gk-math\" data-tex=\"2\">2</span>，<span class=\"gk-math\" data-tex=\"\\dots\">\\dots</span>，<span class=\"gk-math\" data-tex=\"4m+2\">4m+2</span> 中不放回任取 <span class=\"gk-math\" data-tex=\"i&lt;j\">i&lt;j</span>，设 <span class=\"gk-math\" data-tex=\"a_1\">a_1</span>，<span class=\"gk-math\" data-tex=\"\\dots\">\\dots</span>，<span class=\"gk-math\" data-tex=\"a_{4m+2}\">a_{4m+2}</span> 是 <span class=\"gk-math\" data-tex=\"(i,j)\">(i,j)</span>-可分数列的概率为 <span class=\"gk-math\" data-tex=\"P_m\">P_m</span>，证明 <span class=\"gk-math\" data-tex=\"P_m&gt;\\frac18\">P_m&gt;\\frac18</span>.</li></ol>","optionsHtml":[],"answerHtml":"<span>见下方分步解析</span>","answerKey":"","solutionHtml":"因为 <span class=\"gk-math\" data-tex=\"a_n=a_1+(n-1)d\">a_n=a_1+(n-1)d</span> 且 <span class=\"gk-math\" data-tex=\"d\\ne0\">d\\ne0</span>，四个数列项成等差数列，当且仅当它们的四个下标成等差数列。因此只需研究下标。 <ol class=\"gk-subparts\"><li>在 <span class=\"gk-math\" data-tex=\"1,2,3,4,5,6\">1,2,3,4,5,6</span> 中，四个不同整数成等差数列只能取连续四个数：<span class=\"gk-math\" data-tex=\"\\{1,2,3,4\\}\">\\{1,2,3,4\\}</span>、<span class=\"gk-math\" data-tex=\"\\{2,3,4,5\\}\">\\{2,3,4,5\\}</span>、<span class=\"gk-math\" data-tex=\"\\{3,4,5,6\\}\">\\{3,4,5,6\\}</span>。相应删去的两项下标为 <span class=\"gk-math\" data-tex=\"(5,6),(1,6),(1,2)\">(5,6),(1,6),(1,2)</span>。</li><li>去掉 <span class=\"gk-math\" data-tex=\"2,13\">2,13</span> 后，先分成三组： <div class=\"gk-math display\" data-tex=\"\\{1,4,7,10\\},\\quad\\{3,6,9,12\\},\\quad\\{5,8,11,14\\}.\">\\{1,4,7,10\\},\\quad\\{3,6,9,12\\},\\quad\\{5,8,11,14\\}.</div> 其余下标从 <span class=\"gk-math\" data-tex=\"15\">15</span> 到 <span class=\"gk-math\" data-tex=\"4m+2\">4m+2</span>，每连续四个分为一组，正好再得 <span class=\"gk-math\" data-tex=\"m-3\">m-3</span> 组。因此总共 <span class=\"gk-math\" data-tex=\"m\">m</span> 组，每组都成等差数列。</li><li>我们数出一部分肯定可分的删法，就能得到概率下界。<br><br>先用到一个构造：对每个整数 <span class=\"gk-math\" data-tex=\"h\\ge2\">h\\ge2</span>，从 <span class=\"gk-math\" data-tex=\"1,\\ldots,4h+2\">1,\\ldots,4h+2</span> 删去 <span class=\"gk-math\" data-tex=\"2,4h+1\">2,4h+1</span> 后，余下的数能按题意分组。<span class=\"gk-math\" data-tex=\"h=2\">h=2</span> 时可取 <span class=\"gk-math\" data-tex=\"\\{1,3,5,7\\},\\{4,6,8,10\\}\">\\{1,3,5,7\\},\\{4,6,8,10\\}</span>；<span class=\"gk-math\" data-tex=\"h=3\">h=3</span> 时用第（2）问的三组。若对 <span class=\"gk-math\" data-tex=\"h\">h</span> 已有分组，扩展到 <span class=\"gk-math\" data-tex=\"h+2\">h+2</span> 时保留原分组，再加两组 <div class=\"gk-math display\" data-tex=\"\\{4h+1,4h+3,4h+5,4h+7\\},\\qquad\n\\{4h+4,4h+6,4h+8,4h+10\\}.\">\\{4h+1,4h+3,4h+5,4h+7\\},\\qquad\n\\{4h+4,4h+6,4h+8,4h+10\\}.</div> 这样恰好从新范围中删掉 <span class=\"gk-math\" data-tex=\"2,4h+9\">2,4h+9</span>，所以由两个初始情形出发，所有 <span class=\"gk-math\" data-tex=\"h\\ge2\">h\\ge2</span> 都成立。<br><br>记 <span class=\"gk-math\" data-tex=\"A=\\{1,5,\\ldots,4m+1\\}\">A=\\{1,5,\\ldots,4m+1\\}</span>，<span class=\"gk-math\" data-tex=\"B=\\{2,6,\\ldots,4m+2\\}\">B=\\{2,6,\\ldots,4m+2\\}</span>，两个集合都含 <span class=\"gk-math\" data-tex=\"m+1\">m+1</span> 个数。从A、B各选一个数删去，共 <span class=\"gk-math\" data-tex=\"(m+1)^2\">(m+1)^2</span> 对。 若较小的数来自A、较大的数来自B，则删去两数前、两数之间、两数之后，剩余下标都可每连续四个分一组。 若较小数为 <span class=\"gk-math\" data-tex=\"4r+2\">4r+2</span>、较大数为 <span class=\"gk-math\" data-tex=\"4s+1\">4s+1</span>，其中 <span class=\"gk-math\" data-tex=\"s\\ge r+2\">s\\ge r+2</span>，则中间整段 <span class=\"gk-math\" data-tex=\"4r+1,\\ldots,4s+2\">4r+1,\\ldots,4s+2</span> 平移后就是上面 <span class=\"gk-math\" data-tex=\"h=s-r\">h=s-r</span> 的构造，两侧剩余下标仍可每连续四个分组。<br><br>因此这些跨A、B的删法中，只需排除相差3的 <span class=\"gk-math\" data-tex=\"m\">m</span> 对 <span class=\"gk-math\" data-tex=\"(2,5),(6,9),\\ldots,(4m-2,4m+1)\">(2,5),(6,9),\\ldots,(4m-2,4m+1)</span>，就至少有 <span class=\"gk-math\" data-tex=\"m^2+m+1\">m^2+m+1</span> 对可分。全部等可能删法共有 <span class=\"gk-math\" data-tex=\"\\binom{4m+2}{2}=(2m+1)(4m+1)\">\\binom{4m+2}{2}=(2m+1)(4m+1)</span>，所以 <div class=\"gk-math display\" data-tex=\"P_m\\ge\\frac{m^2+m+1}{(2m+1)(4m+1)}&gt;\\frac18.\">P_m\\ge\\frac{m^2+m+1}{(2m+1)(4m+1)}&gt;\\frac18.</div> 最后一个不等式只需交叉相乘：左边分子乘8后比右边分母多 <span class=\"gk-math\" data-tex=\"2m+7&gt;0\">2m+7&gt;0</span>。</li></ol>","sourceNote":"","specialNote":"","answerAlternatives":[]}];
